{"explanation":"In vertex form y = a(x − h)² + k, the point (h, k) is the vertex, the turning point of the parabola. **h** moves the parabola left and right. Because of the minus sign, (x − 2) moves it 2 units to the *right*. **k** moves it up and down. **a** changes the shape: if |a| > 1 the parabola gets narrower, if |a| < 1 it gets wider, and if a is negative it flips upside down. Move the sliders and compare the yellow curve with the gray y = x² for reference. The red dot marks the vertex, and the dashed line through it is the axis of symmetry, x = h.","manimCode":"const ax = new Axes({ xRange: [-6, 6, 1], yRange: [-5, 5, 1], xLength: 9, yLength: 6.6, tips: false });
ax.moveTo([-1.8, -0.3, 0]);
scene.add(ax);

let a = 1, h = 0, k = 0;
const YMAX = 5, XMIN = -6, XMAX = 6;

function plotRange(A, H, K) {
  if (Math.abs(A) < 1e-6) {
    if (Math.abs(K) > YMAX) return null;
    return [XMIN, XMAX];
  }
  const lim = A > 0 ? (YMAX - K) / A : (-YMAX - K) / A;
  if (lim < 0) return null;
  const r = Math.sqrt(lim);
  const lo = Math.max(XMIN, H - r), hi = Math.min(XMAX, H + r);
  if (hi - lo < 0.01) return null;
  return [lo, hi];
}

// reference parabola y = x^2
const ref = ax.plot(x => x * x, { color: GRAY, xRange: [-Math.sqrt(5), Math.sqrt(5)], numSamples: 200 });
ref.setStrokeWidth(2);
ref.setOpacity(0.5);
scene.add(ref);

let curve = null;
function rebuildCurve() {
  if (curve) scene.remove(curve);
  curve = null;
  const rng = plotRange(a, h, k);
  if (!rng) return;
  const A = a, H = h, K = k;
  curve = ax.plot(x => A * (x - H) * (x - H) + K, { color: YELLOW, xRange: rng, numSamples: 300 });
  curve.setStrokeWidth(4);
  scene.add(curve);
}

// axis of symmetry, drawn as short dashes
let dashes = [];
function rebuildAxis() {
  dashes.forEach(d => scene.remove(d));
  dashes = [];
  for (let y = -5; y < 5; y += 0.5) {
    const seg = new Polygon({ vertices: [ax.c2p(h, y), ax.c2p(h, y + 0.25)], color: TEAL });
    seg.setStrokeWidth(2);
    seg.setFillOpacity(0);
    dashes.push(seg);
    scene.add(seg);
  }
}

const vertex = new Dot({ point: ax.c2p(h, k), color: RED });
scene.add(vertex);
const inView = () => Math.abs(k) <= 5;

let vLabel = null;
function rebuildVertexLabel() {
  if (vLabel) scene.remove(vLabel);
  vLabel = new Text({ text: `(${h.toFixed(1)}, ${k.toFixed(1)})`, color: RED_A, fontSize: 20 });
  vLabel.moveTo(ax.c2p(h, k));
  vLabel.shift([0, a >= 0 ? -0.35 : 0.35, 0]);
  scene.add(vLabel);
}

// equation label
const f = v => v.toFixed(1);
let eq = null;
let eqToken = 0;
async function rebuildEq() {
  const my = ++eqToken;
  const hPart = h === 0 ? 'x' : (h > 0 ? `(x - ${f(h)})` : `(x + ${f(-h)})`);
  const kPart = k === 0 ? '' : (k > 0 ? ` + ${f(k)}` : ` - ${f(-k)}`);
  const latex = `y = {\\color{orange}${f(a)}}\\,${hPart.replace('x', 'x').replace(/(-|\+) ([\d.]+)/, (m, s, n) => `${s} {\\color{teal}${n}}`)}^2${kPart.replace(/([\d.]+)/, n => `{\\color{red}${n}}`)}`;
  const t = new MathTex({ latex: latex, fontSize: 34 });
  await t.waitForRender();
  if (my !== eqToken) return;
  if (eq) scene.remove(eq);
  eq = t;
  eq.moveTo([-1.8, 3.55, 0]);
  scene.add(eq);
}

function refresh() {
  rebuildCurve();
  rebuildAxis();
  vertex.moveTo(ax.c2p(h, Math.max(-5, Math.min(5, k))));
  vertex.setOpacity(inView() ? 1 : 0);
  rebuildVertexLabel();
  rebuildEq();
}
refresh();

const legend = new Text({ text: 'gray: y = x²', color: GRAY, fontSize: 18 });
legend.moveTo([4.6, -3.5, 0]);
scene.add(legend);

const controls = new Controls(scene, { position: 'top-right', width: 260 });
controls.addSlider({ label: 'a (stretch / flip)', min: -3, max: 3, value: 1, step: 0.1, onChange: v => { a = Math.round(v * 10) / 10; refresh(); } });
controls.addSlider({ label: 'h (horizontal shift)', min: -4, max: 4, value: 0, step: 0.1, onChange: v => { h = Math.round(v * 10) / 10; refresh(); } });
controls.addSlider({ label: 'k (vertical shift)', min: -4, max: 4, value: 0, step: 0.1, onChange: v => { k = Math.round(v * 10) / 10; refresh(); } });

await scene.wait(999999);"}

